  "claims": [
    {
      "text": "Yes—when a Deputy Registrar exercises a power or function of the Registrar, section 205(3) treats it as having been exercised by the Registrar.",
      "quotes": [
        {
          "ref": "TMA1995/s205",
          "quote": "(3) A power or function of the Registrar, when exercised by a Deputy Registrar, is taken to have been exercised by the Registrar."
        }
      ],
      "authority": "legislation"
    },
    {
      "text": "A Deputy Registrar has all the Registrar’s powers and functions, subject to any direction by the Registrar, except the powers of delegation under section 206.",
      "quotes": [
        {
          "ref": "TMA1995/s205",
          "quote": "(2) Subject to any direction by the Registrar, a Deputy Registrar has all the powers and functions of the Registrar, except the powers of delegation under section 206."
        }
      ],
      "authority": "legislation"
    },
    {
      "text": "Consistently with that statutory treatment, the Manual says decisions issued by a Deputy Registrar are headed “Decision of the Registrar of Trade Marks, with Reasons”, rather than as decisions of a delegate.",
      "quotes": [
        {
          "ref": "TMM/Part52/1#1~2",
          "quote": "Therefore, decisions issued by the Deputy Registrar are headed \"Decision of the Registrar of Trade Marks, with Reasons\" rather than “Decision of a delegate of the Registrar of Trade marks” (emphasis added)."
        }
      ],
      "authority": "manual"
    }
  ],
  "declined": false,
  "concepts_used": [
    "GC-0159",
    "GC-0046",
    "GC-0127"
  ]
}
